using System;
using EmberBastion;
class LossRetryInfoChecks {
 static void Check(bool ok,string msg){if(!ok)throw new Exception(msg);}
 static void Main(){var original=new Battle(1,0);Check(original.Place(0,0),"place");var prep=original.SavePreparation();Check(original.Start(),"start");var wave=original.CopyCombat();original.Gold=500;var info=LossRetryInfo.For(original,wave,prep);Check(info.Restores&&info.Gold==135&&info.Empty==wave.Field.Slots.Length-1&&info.Advice()=="빈 자리에 병력 추가","wave checkpoint wins");wave.Gold=20;info=LossRetryInfo.For(original,wave,prep);Check(info.Gold==20&&info.Advice()=="병과와 배치를 바꿔 보세요","checkpoint affordability");info=LossRetryInfo.For(original,null,prep);Check(info.Gold==135&&info.Restores,"preparation checkpoint");info=LossRetryInfo.For(original,null,null);Check(info.Gold==500&&!info.Restores&&info.Advice()=="새 전투에서 편성을 바꿔 보세요","no checkpoint");wave.Gold=49;wave.Units[0].Level=1;info=LossRetryInfo.For(original,wave,null);Check(!info.CanUpgrade,"level 1 below threshold");wave.Gold=50;info=LossRetryInfo.For(original,wave,null);Check(info.CanUpgrade&&info.Advice()=="병력을 강화해 보세요","level 1 threshold");wave.Units[0].Level=2;wave.Gold=89;info=LossRetryInfo.For(original,wave,null);Check(!info.CanUpgrade,"level 2 below threshold");wave.Gold=90;info=LossRetryInfo.For(original,wave,null);Check(info.CanUpgrade,"level 2 threshold");wave.Enemies.Clear();for(int i=0;i<69;i++)wave.Enemies.Add(new Enemy{HP=1});info=LossRetryInfo.For(original,wave,null);Check(info.HasWave&&info.Enemies==69&&info.Advice()!="복원 시점도 위험 · 재도전 고려","69 enemies remain below risk threshold");wave.Enemies.Add(new Enemy{HP=1});info=LossRetryInfo.For(original,wave,null);Check(info.Enemies==70&&info.Advice()=="복원 시점도 위험 · 재도전 고려","70 enemies warns about risky retry");info=LossRetryInfo.For(original,null,prep);Check(!info.HasWave,"preparation checkpoint has no surviving enemies");Console.WriteLine("PASS loss advice uses actual retry resources");}
}
